  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="support-card" aria-labelledby="support-title">
        <h1 id="support-title">Contact support</h1>
        <p class="intro">
          Tell us how to reach you and our support team will follow up as soon as possible.
        </p>
        <p class="required-note">
          Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
        </p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">
              Full name <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
            >
            <p class="error-message" id="full-name-error"></p>
          </div>

          <div class="form-field">
            <label for="email">
              Email address <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              required
              aria-describedby="email-error"
            >
            <p class="error-message" id="email-error"></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number (optional)</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-help phone-error"
            >
            <p class="help-text" id="phone-help">Use 10 digits, with optional spaces, dashes, parentheses, or a leading + country code.</p>
            <p class="error-message" id="phone-error"></p>
          </div>

          <button type="submit">Contact support</button>
          <p class="success-message" id="form-status" role="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#support-form");
      const fields = {
        fullName: {
          input: document.querySelector("#full-name"),
          error: document.querySelector("#full-name-error"),
          validate(value) {
            return value.trim() ? "" : "Error: Enter your full name.";
          },
        },
        email: {
          input: document.querySelector("#email"),
          error: document.querySelector("#email-error"),
          validate(value) {
            const trimmedValue = value.trim();

            if (!trimmedValue) {
              return "Error: Enter your email address.";
            }

            if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)) {
              return "Error: Enter a valid email address, like name@example.com.";
            }

            return "";
          },
        },
        phone: {
          input: document.querySelector("#phone"),
          error: document.querySelector("#phone-error"),
          validate(value) {
            const trimmedValue = value.trim();

            if (!trimmedValue) {
              return "";
            }

            if (!/^\+?[0-9\s().-]{10,20}$/.test(trimmedValue)) {
              return "Error: Enter a phone number using digits, spaces, dashes, parentheses, or a leading +.";
            }

            return "";
          },
        },
      };
      const status = document.querySelector("#form-status");

      function setFieldError(field, message) {
        field.error.textContent = message;

        if (message) {
          field.input.setAttribute("aria-invalid", "true");
        } else {
          field.input.removeAttribute("aria-invalid");
        }
      }

      function validateField(field) {
        const message = field.validate(field.input.value);
        setFieldError(field, message);
        return !message;
      }

      Object.values(fields).forEach((field) => {
        field.input.addEventListener("input", () => {
          validateField(field);
          status.textContent = "";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const invalidField = Object.values(fields).find((field) => !validateField(field));

        if (invalidField) {
          status.textContent = "";
          invalidField.input.focus();
          return;
        }

        form.reset();
        Object.values(fields).forEach((field) => setFieldError(field, ""));
        status.textContent = "Thanks. Your support request is ready to send.";
      });
    </script>
  </body>
</html>
