          <div class="form-field">
            <label for="full-name">
              Full name <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
            >
            <p class="error-message" id="full-name-error"></p>
          </div>

          <div class="form-field">
            <label for="email">
              Email address <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              required
              aria-describedby="email-error"
            >
            <p class="error-message" id="email-error"></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number (optional)</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-help phone-error"
            >
            <p class="help-text" id="phone-help">Use 10 digits, with optional spaces, dashes, parentheses, or a leading + country code.</p>
            <p class="error-message" id="phone-error"></p>
          </div>

          <button type="submit">Contact support</button>
          <p class="success-message" id="form-status" role="status" aria-live="polite"></p>
        </form>
      </section>
